import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u10")
C = "A2-B1"
# Lições de aprofundamento (10–22): problemas do dia a dia e como resolvê-los.

L(10, "Água em casa", "Een lekkage en een verstopte afvoer.",
  ["Descrever problemas de canalização e pedir ajuda"],
  vocab=[V("v-lekkage","lekkage","fuga de água|infiltração","noun","de"), V("v-verstopt","verstopt","entupido","adjective"),
         V("v-afvoer","afvoer","esgoto|ralo","noun","de"), V("v-druppelen","druppelen","pingar","verb")],
  ex=[("We hebben een lekkage in de badkamer.","Temos uma fuga de água na casa de banho."),("De gootsteen is verstopt.","O lava-loiça está entupido."),("Het water loopt niet weg door de afvoer.","A água não escoa pelo ralo."),("De kraan druppelt de hele nacht.","A torneira pinga a noite toda.")],
  review=["v-loodgieter","v-kraan","v-lekken"],
  cefr=C, exs=[
    MA([("lekkage","fuga de água"),("verstopt","entupido"),("afvoer","ralo/esgoto"),("druppelen","pingar")], "Canalização.", ["v-lekkage","v-verstopt","v-afvoer","v-druppelen"]),
    TR("pt-nl","O lava-loiça está entupido.", ["De gootsteen is verstopt"], "verstopt.", ["v-verstopt"]),
    TR("pt-nl","A torneira está a pingar.", ["De kraan druppelt","De kraan lekt"], "druppelen / lekken.", ["v-druppelen","v-kraan"]),
    DL([("Loodgieter","Loodgietersbedrijf Van Dam, goedemorgen.","Canalizador Van Dam, bom dia."),("Huurder","","")], ["*Goedemorgen, er is een lekkage onder de wastafel en het water loopt over de vloer.","Ik ben een lekkage.|Não faz sentido.","Ik wil een kraan kopen, dag.|Não explica o problema."], "Descrever o problema com clareza.", ["v-lekkage"]),
    MC("Há água a pingar do teto. Diz-se…", ["*Er is een lekkage bij de buren boven.","De afvoer is verstopt.|Isso é entupimento.","De kraan is uit.|Não."], "lekkage.", ["v-lekkage"]),
    AR("afvoer","o ralo","de", "De afvoer.", ["v-afvoer"]),
    CO("text","Wat te doen bij een lekkage?", "Ontdek je een lekkage? Draai dan meteen de hoofdkraan dicht. Zet emmers neer en haal spullen weg van de natte plek. Maak foto's voor de verzekering. Huur je een woning? Bel dan zo snel mogelijk je verhuurder. Is het lek bij de buren boven? Bel bij hen aan, want misschien weten ze het zelf nog niet.",
       [("Qual é o primeiro passo?", ["*Fechar a torneira principal","Ligar ao seguro","Limpar o chão"]),("Para que servem as fotos?", ["*Para o seguro","Para as redes sociais","Para o canalizador"]),("Se é inquilino, a quem liga?", ["*Ao senhorio","À câmara","À polícia"])],
       "Instruções com imperativos.", ["v-lekkage"]),
    FE(["De","wc","is","verstopte."], 3, "verstopt", "Predicativo: sem -e.", ["v-verstopt"]),
    LI("Het water loopt niet meer weg.", ["Het water loopt niet meer weg"], "A água já não escoa.", "weglopen (água) = escoar.", ["v-afvoer"]),
    WO("Temos uma fuga de água na casa de banho.", ["We","hebben","een","lekkage","in","de","badkamer"], "Ordem simples.", ["v-lekkage"]),
  ], diff=3, mins=6)

