    TR("pt-nl","Está um gelo em casa.", ["Het is ijskoud in huis","Het is ijskoud thuis"], "ijs + koud.", ["v-ijskoud"]),
    DL([("Storingsdienst","Storingsdienst, goedemiddag. Wat is er aan de hand?","Serviço de avarias, boa tarde. O que se passa?"),("Bewoner","","")], ["*Sinds gisteren hebben we geen warm water en de cv-ketel geeft foutcode F28.","Ik heb het warm.|Não é um problema técnico.","Ik wil een nieuwe badkamer.|Não responde."], "Dar informação concreta (desde quando, código).", ["v-cv-ketel","v-sinds-gisteren"]),
    CO("dialogue","Een afspraak met de monteur", "Medewerker: We kunnen morgen tussen acht en één een monteur sturen.\nRita: Kan het niet vandaag? We hebben een baby en het is ijskoud.\nMedewerker: Ik begrijp het. Ik zet u op de spoedlijst; de monteur komt vanavond tussen zes en negen.\nRita: Fijn, dank u wel!",
       [("Quando estava marcada a visita?", ["*Amanhã de manhã","Hoje à tarde","Para a semana"]),("Porque pede urgência a Rita?", ["*Tem um bebé e está muito frio","Vai viajar","Tem visitas"]),("Quando vem o técnico?", ["*Hoje entre as 18h e as 21h","Amanhã às 8h","Daqui a uma semana"])],
       "Pedir prioridade com justificação.", ["v-storingsdienst","v-ijskoud"]),
