L(17, "Um mal-entendido", "Er is een misverstand ontstaan.",
  ["Esclarecer um mal-entendido com calma"],
  vocab=[V("v-misverstand","misverstand","mal-entendido","noun","het"), V("v-verkeerd-begrijpen","verkeerd begrijpen","perceber mal","expression"),
         V("v-ophelderen","ophelderen","esclarecer","verb"), V("v-zo-bedoelde-ik-het-niet","zo bedoelde ik het niet","não era isso que eu queria dizer","expression")],
  ex=[("Er is een misverstand.","Há um mal-entendido."),("Ik heb je verkeerd begrepen.","Percebi-te mal."),("Laten we dit even ophelderen.","Vamos esclarecer isto."),("Sorry, zo bedoelde ik het niet.","Desculpa, não era isso que eu queria dizer.")],
  review=["v-bedoelen"],
  cefr=C, exs=[
    MA([("misverstand","mal-entendido"),("verkeerd begrijpen","perceber mal"),("ophelderen","esclarecer"),("zo bedoelde ik het niet","não queria dizer isso")], "Mal-entendidos.", ["v-misverstand","v-verkeerd-begrijpen","v-ophelderen","v-zo-bedoelde-ik-het-niet"]),
    AR("misverstand","o mal-entendido","het", "Het verstand → het misverstand.", ["v-misverstand"]),
    TR("pt-nl","Percebi-te mal.", ["Ik heb je verkeerd begrepen","Ik heb jou verkeerd begrepen"], "begrijpen → begrepen.", ["v-verkeerd-begrijpen"]),
    TR("pt-nl","Vamos esclarecer isto.", ["Laten we dit even ophelderen","Laten we dit ophelderen"], "ophelderen.", ["v-ophelderen"]),
    CO("dialogue","Een misverstand op het werk", "Kim: Waarom heb je het rapport niet gestuurd? De klant wacht!\nPedro: Welk rapport? Ik dacht dat jij het zou sturen.\nKim: Nee, ik had gezegd dat jij het moest doen.\nPedro: O, dan heb ik je verkeerd begrepen. Er is een misverstand ontstaan. Ik stuur het nu meteen.\nKim: Prima. Laten we voortaan de taken even op papier zetten.",
       [("Qual é o problema?", ["*O relatório não foi enviado","O cliente cancelou","O Pedro está doente"]),("O que pensava o Pedro?", ["*Que a Kim ia enviar","Que não era preciso","Que já tinha enviado"]),("Que solução propõe a Kim?", ["*Escrever as tarefas","Mudar de equipa","Falar com o chefe"])],
       "Esclarecer sem acusar.", ["v-misverstand","v-verkeerd-begrijpen"]),
    DL([("Vriendin","Vind je mijn nieuwe kapsel lelijk?","Achas o meu corte de cabelo novo feio?"),("Marta","","")], ["*Nee! Sorry, zo bedoelde ik het niet. Ik zei alleen dat het anders is.","Ja, lelijk.|Rude.","Ik heb je kapsel opgehelderd.|Não faz sentido."], "Corrigir uma má interpretação.", ["v-zo-bedoelde-ik-het-niet"]),
    FE(["Ik","heb","je","verkeerd","begrijpt."], 4, "begrepen", "Particípio irregular: begrepen.", ["v-verkeerd-begrijpen"]),
    FB("Dat was een ___: we stonden allebei bij een ander station te wachten!", ["misverstand"], "Mal-entendido.", ["v-misverstand"], choices=["misverstand","verklaring","probleem"], tr="Foi um mal-entendido: estávamos os dois à espera em estações diferentes!"),
    LI("Ik denk dat er een misverstand is ontstaan.", ["Ik denk dat er een misverstand is ontstaan","Ik denk dat er een misverstand ontstaan is"], "Acho que surgiu um mal-entendido.", "ontstaan = surgir.", ["v-misverstand"]),
    WO("Desculpa, não era isso que eu queria dizer.", ["Sorry,","zo","bedoelde","ik","het","niet"], "Inversão depois de «zo».", ["v-zo-bedoelde-ik-het-niet"]),
  ], diff=3, mins=7)

L(18, "Pedir conselho", "Wat zou jij doen?",
  ["Pedir e dar conselhos sobre um problema"],
  vocab=[V("v-wat-zou-jij-doen","wat zou jij doen?","o que farias tu?","expression"), V("v-als-ik-jou-was","als ik jou was","se eu fosse a ti","expression"),
         V("v-aanraden","aanraden","aconselhar","verb"), V("v-het-beste","het beste","o melhor","expression")],
  ex=[("Wat zou jij doen?","O que farias tu?"),("Als ik jou was, zou ik het gewoon vragen.","Se eu fosse a ti, perguntava simplesmente."),("Ik raad je aan om een advocaat te bellen.","Aconselho-te a ligar a um advogado."),("Het beste is om rustig te blijven.","O melhor é manteres a calma.")],
  review=["v-advies","v-je-zou-kunnen"],
  cefr=C, exs=[
    MA([("wat zou jij doen?","o que farias?"),("als ik jou was","se eu fosse a ti"),("aanraden","aconselhar"),("het beste","o melhor")], "Conselhos.", ["v-wat-zou-jij-doen","v-als-ik-jou-was","v-aanraden","v-het-beste"]),
    TR("pt-nl","O que farias tu?", ["Wat zou jij doen","Wat zou jij doen?","Wat zou je doen"], "zou + infinitivo.", ["v-wat-zou-jij-doen"]),
    BS("Se eu fosse a ti, ligava ao senhorio.", ["Als","ik","jou","was,","zou","ik","de","verhuurder","bellen","belde"], ["Als ik jou was, zou ik de verhuurder bellen"], "Hipótese: als … was, zou … + infinitivo.", ["v-als-ik-jou-was"]),
    CJ("aanraden","de dokter","De dokter heeft me rust ___.", ["aangeraden"], "aan-ge-raden.", ["v-aanraden"], tense="passado-perfeito"),
    DL([("Collega","Mijn buren maken elke nacht lawaai. Wat zou jij doen?","Os meus vizinhos fazem barulho todas as noites. O que farias?"),("Rui","","")], ["*Als ik jou was, zou ik eerst rustig met ze praten.","Ik zou lawaai maken.|Não ajuda.","Wat zou jij doen?|Devolve a pergunta."], "Dar um conselho.", ["v-als-ik-jou-was"]),
    FE(["Als","ik","jou","ben,","zou","ik","bellen."], 3, "was", "Hipótese: als ik jou was.", ["v-als-ik-jou-was"]),
    FB("Ik ___ je aan om het contract goed te lezen.", ["raad"], "aanraden: raad … aan.", ["v-aanraden"], choices=["raad","raadt","geraden"], tr="Aconselho-te a ler bem o contrato."),
    MC("Qual é o conselho mais suave?", ["*Je zou eens met je baas kunnen praten.","Praat met je baas!|Mais direto.","Je moet met je baas praten.|Mais forte."], "zou … kunnen = sugestão suave.", ["v-je-zou-kunnen"]),
    LI("Het beste is om eerst alles op papier te zetten.", ["Het beste is om eerst alles op papier te zetten"], "O melhor é primeiro pôr tudo por escrito.", "om … te.", ["v-het-beste"]),
    WO("O que farias tu?", ["Wat","zou","jij","doen?"], "Pergunta.", ["v-wat-zou-jij-doen"]),
  ], diff=3, mins=6)

L(19, "Procurar soluções", "Welke opties hebben we?",
  ["Analisar opções e escolher uma solução"],
  vocab=[V("v-optie","optie","opção","noun","de","opties"), V("v-bedenken","bedenken","pensar em|inventar","verb"),
         V("v-afwegen","afwegen","ponderar","verb"), V("v-de-beste-keuze","de beste keuze","a melhor escolha","expression")],
  ex=[("Welke opties hebben we?","Que opções temos?"),("Laten we samen een oplossing bedenken.","Vamos pensar juntos numa solução."),("We moeten de voor- en nadelen afwegen.","Temos de ponderar os prós e contras."),("Dit is de beste keuze.","Esta é a melhor escolha.")],
  review=["v-oplossing","v-voordeel","v-nadeel"],
  cefr=C, exs=[
    MA([("optie","opção"),("bedenken","pensar em"),("afwegen","ponderar"),("de beste keuze","a melhor escolha")], "Soluções.", ["v-optie","v-bedenken","v-afwegen","v-de-beste-keuze"]),
    TR("pt-nl","Que opções temos?", ["Welke opties hebben we","Welke opties hebben wij"], "welke + plural.", ["v-optie"]),
    TR("pt-nl","Vamos pensar numa solução.", ["Laten we een oplossing bedenken","Laten we samen een oplossing bedenken"], "bedenken.", ["v-bedenken","v-oplossing"]),
    CO("text","Te weinig ruimte in huis", "Familie Gomes woont met drie kinderen in een appartement met twee slaapkamers. Ze hebben drie opties bedacht. Optie 1: verhuizen naar een groter huis, maar dat is duur en de wachtlijsten zijn lang. Optie 2: de woonkamer verbouwen en een extra slaapkamer maken. Optie 3: de zolder ombouwen. Na lang afwegen kiezen ze optie 3: het is goedkoper en de kinderen kunnen op hun school blijven.",
       [("Qual é o problema?", ["*Pouco espaço em casa","Barulho","Renda alta"]),("Porque não se mudam?", ["*É caro e há longas listas de espera","Gostam da casa","Não podem"]),("O que escolhem?", ["*Transformar o sótão","Mudar-se","Dividir a sala"])],
       "Estrutura: problema, opções, ponderação, escolha.", ["v-optie","v-afwegen","v-bedenken"]),
    CJ("bedenken","wij","We hebben drie opties ___.", ["bedacht"], "bedenken → bedacht (irregular, sem ge-).", ["v-bedenken"], tense="passado-perfeito"),
    FB("Na lang ___ hebben we voor de trein gekozen.", ["afwegen"], "Ponderar.", ["v-afwegen"], choices=["afwegen","bedenken","opties"], tr="Depois de muito ponderar escolhemos o comboio."),
    FE(["We","hebben","een","oplossing","bedenkt."], 4, "bedacht", "Particípio irregular: bedacht.", ["v-bedenken"]),
    MC("Qual é a frase que conclui?", ["*Daarom kiezen we voor optie 2.","Er zijn drie opties.|Introdução.","Een nadeel is de prijs.|Análise."], "Conclusão com daarom.", ["v-de-beste-keuze"]),
    LI("Een nadeel van deze optie is de prijs.", ["Een nadeel van deze optie is de prijs"], "Uma desvantagem desta opção é o preço.", "nadeel van.", ["v-optie"]),
    WO("Esta é a melhor escolha.", ["Dit","is","de","beste","keuze"], "Superlativo.", ["v-de-beste-keuze"]),
  ], diff=3, mins=7)

L(20, "Reclamar por escrito", "Een klachtbrief schrijven.",
  ["Escrever uma reclamação estruturada"],
  vocab=[V("v-klachtbrief","klachtbrief","carta de reclamação","noun","de"), V("v-ontevredenheid","ontevredenheid","insatisfação","noun","de"),
         V("v-vergoeding","vergoeding","indemnização|compensação","noun","de"), V("v-binnen-veertien-dagen","binnen veertien dagen","no prazo de catorze dias","expression")],
  ex=[("Ik schrijf een klachtbrief.","Escrevo uma carta de reclamação."),("Hierbij uit ik mijn ontevredenheid over uw service.","Pela presente manifesto a minha insatisfação com o vosso serviço."),("Ik verzoek u om een vergoeding.","Solicito-lhe uma indemnização."),("Graag ontvang ik binnen veertien dagen een reactie.","Gostaria de receber uma resposta no prazo de catorze dias.")],
  review=["v-klacht-indienen","v-hierbij","v-ontevreden"],
  cefr=C, exs=[
    MA([("klachtbrief","carta de reclamação"),("ontevredenheid","insatisfação"),("vergoeding","indemnização"),("binnen veertien dagen","em 14 dias")], "Reclamação.", ["v-klachtbrief","v-ontevredenheid","v-vergoeding","v-binnen-veertien-dagen"]),
    MC("Qual é a ordem lógica de uma reclamação?", ["*o que aconteceu → porque é inaceitável → o que pede → prazo","pedido → insulto → assinatura|Não.","só o pedido|Falta contexto."], "Estrutura clara.", ["v-klachtbrief"]),
    TR("pt-nl","Solicito uma indemnização.", ["Ik verzoek u om een vergoeding","Ik vraag om een vergoeding","Graag ontvang ik een vergoeding"], "verzoeken om (formal).", ["v-vergoeding"]),
    CO("text","Klachtbrief", "Geachte heer/mevrouw,\nOp 12 april heb ik bij uw hotel in Maastricht overnacht (reserveringsnummer 7781). Helaas was mijn ervaring zeer teleurstellend. De kamer was niet schoon, de verwarming deed het niet en de receptie was 's avonds onbereikbaar. Hierbij dien ik een klacht in. Ik verzoek u om een gedeeltelijke vergoeding van de kosten. Graag ontvang ik binnen veertien dagen een reactie.\nMet vriendelijke groet,\nC. Rocha",
       [("Quais foram os problemas?", ["*Quarto sujo, aquecimento avariado, receção inacessível","Barulho e preço","Comida má"]),("O que pede?", ["*Um reembolso parcial","Uma noite grátis","Desculpas apenas"]),("Em quanto tempo quer resposta?", ["*Catorze dias","Um dia","Um mês"])],
       "Reclamação formal completa.", ["v-klachtbrief","v-vergoeding","v-binnen-veertien-dagen"]),
    FE(["Ik","verzoek","u","voor","een","vergoeding."], 3, "om", "verzoeken om.", ["v-vergoeding"]),
    FB("Graag ontvang ik binnen veertien ___ een reactie.", ["dagen"], "Prazo.", ["v-binnen-veertien-dagen"], choices=["dagen","dag","weken"], tr="Gostaria de receber uma resposta no prazo de catorze dias."),
    AR("vergoeding","a indemnização","de", "-ing → de.", ["v-vergoeding"]),
    LI("Helaas was mijn ervaring zeer teleurstellend.", ["Helaas was mijn ervaring zeer teleurstellend"], "Infelizmente a minha experiência foi muito dececionante.", "Inversão depois de helaas.", ["v-ontevredenheid"]),
    SW("Escreva uma reclamação curta (5–6 frases) a uma loja online: o que encomendou, o problema, o que pede e prazo.", ["Geachte heer/mevrouw,\nOp 2 mei heb ik bij uw webwinkel een stofzuiger besteld (bestelnummer 55012). Het pakket kwam pas na drie weken aan en de stofzuiger was beschadigd. Hierbij dien ik een klacht in. Ik verzoek u om een nieuwe stofzuiger of mijn geld terug. Graag ontvang ik binnen veertien dagen een reactie.\nMet vriendelijke groet,\nJ. Costa"], ["Data e número", "Problema concreto", "Pedido claro", "Prazo", "Registo formal"], 50, "Reclamação escrita.", ["v-klachtbrief","v-vergoeding"]),
  ], diff=4, mins=8)

L(21, "Problemas na escola", "Mijn dochter wordt gepest.",
  ["Falar com a escola sobre um problema do filho"],
  vocab=[V("v-pesten","pesten","fazer bullying|implicar","verb"), V("v-mentor","mentor","diretor de turma","noun","de"),
         V("v-gesprek-aanvragen","een gesprek aanvragen","pedir uma reunião","expression"), V("v-in-de-gaten-houden","in de gaten houden","estar atento a|vigiar","expression")],
  ex=[("Mijn dochter wordt gepest op school.","A minha filha sofre bullying na escola."),("Ik heb een gesprek aangevraagd met de mentor.","Pedi uma reunião com o diretor de turma."),("De school houdt het in de gaten.","A escola está atenta.")],
  review=["v-ongerust"],
  cefr=C, exs=[
    MA([("pesten","fazer bullying"),("mentor","diretor de turma"),("een gesprek aanvragen","pedir uma reunião"),("in de gaten houden","estar atento")], "Escola.", ["v-pesten","v-mentor","v-gesprek-aanvragen","v-in-de-gaten-houden"]),
    TR("pt-nl","A minha filha sofre bullying.", ["Mijn dochter wordt gepest"], "Passiva: wordt gepest.", ["v-pesten"]),
    TR("pt-nl","Pedi uma reunião com o diretor de turma.", ["Ik heb een gesprek aangevraagd met de mentor","Ik heb een gesprek met de mentor aangevraagd"], "aanvragen.", ["v-gesprek-aanvragen"]),
    CO("dialogue","Gesprek met de mentor", "Mentor: Fijn dat u er bent. Wat is er aan de hand?\nVader: Mijn zoon wordt al weken gepest door een paar jongens uit zijn klas. Hij wil niet meer naar school.\nMentor: Wat vervelend. Dank u dat u het meldt. Ik ga vandaag nog met de jongens praten en ik houd het goed in de gaten.\nVader: Kunnen we over twee weken weer afspreken?\nMentor: Natuurlijk. En als er iets gebeurt, belt u me meteen.",
       [("Há quanto tempo acontece?", ["*Há semanas","Desde ontem","Há um ano"]),("O que vai fazer o professor?", ["*Falar com os rapazes hoje e estar atento","Expulsar os rapazes","Mudar o aluno de turma"]),("O que combinam?", ["*Nova reunião daqui a duas semanas","Nada","Ligar à polícia"])],
       "Conversa construtiva com a escola.", ["v-pesten","v-mentor","v-in-de-gaten-houden"]),
    MC("Nos Países Baixos, no secundário, o primeiro contacto para problemas é normalmente…", ["*a mentor (diretor de turma)","o diretor da escola|Normalmente não é o primeiro.","a polícia|Não."], "mentor = ponto de contacto.", ["v-mentor"]),
    FE(["Hij","wordt","gepesten","door","klasgenoten."], 2, "gepest", "pesten → gepest.", ["v-pesten"]),
    FB("Wilt u het de komende weken goed in de ___ houden?", ["gaten"], "in de gaten houden.", ["v-in-de-gaten-houden"], choices=["gaten","ogen","hand"], tr="Pode estar atento nas próximas semanas?"),
    AR("mentor","o diretor de turma","de", "De mentor.", ["v-mentor"]),
    LI("Ik maak me zorgen, want hij wil niet meer naar school.", ["Ik maak me zorgen, want hij wil niet meer naar school","Ik maak me zorgen want hij wil niet meer naar school"], "Estou preocupado, porque ele já não quer ir à escola.", "want + ordem normal.", ["v-ongerust"]),
    WO("A escola está atenta.", ["De","school","houdt","het","in","de","gaten"], "Expressão fixa.", ["v-in-de-gaten-houden"]),
  ], diff=4, mins=7)

L(22, "Prática: resolver um problema passo a passo", "Probleem, oorzaak, oplossing.",
  ["Descrever um problema, a causa e a solução de forma organizada"],
  vocab=[V("v-oorzaak","oorzaak","causa","noun","de","oorzaken"), V("v-gevolg","gevolg","consequência","noun","het","gevolgen"),
         V("v-stap-voor-stap","stap voor stap","passo a passo","expression")],
  ex=[("Wat is de oorzaak van het probleem?","Qual é a causa do problema?"),("Het gevolg was dat we geen water hadden.","A consequência foi que ficámos sem água."),("We hebben het stap voor stap opgelost.","Resolvemos passo a passo.")],
  review=["v-oplossing","v-optie","v-lekkage","v-storingsdienst"],
  cefr=C, exs=[
    MA([("oorzaak","causa"),("gevolg","consequência"),("stap voor stap","passo a passo"),("oplossing","solução")], "Resolver problemas.", ["v-oorzaak","v-gevolg","v-stap-voor-stap","v-oplossing"]),
    AR("gevolg","a consequência","het", "Het gevolg.", ["v-gevolg"]),
    AR("oorzaak","a causa","de", "De oorzaak.", ["v-oorzaak"]),
    MC("Em «Door de storm viel de stroom uit», qual é a causa?", ["*de storm","de stroom|É a consequência.","viel|É o verbo."], "door = por causa de.", ["v-oorzaak"]),
    TR("pt-nl","Qual é a causa do problema?", ["Wat is de oorzaak van het probleem","Wat is de oorzaak van het probleem?"], "oorzaak van.", ["v-oorzaak"]),
    TR("pt-nl","Resolvemos passo a passo.", ["We hebben het stap voor stap opgelost","Wij hebben het stap voor stap opgelost"], "oplossen → opgelost.", ["v-stap-voor-stap"]),
    CO("text","Een probleem met de afwasmachine", "Vorige week deed onze afwasmachine het niet meer: er bleef water in staan. De oorzaak was een verstopt filter. Het gevolg was een vieze geur in de keuken. We hebben het stap voor stap opgelost: eerst de stekker eruit gehaald, toen het filter schoongemaakt en daarna de machine opnieuw aangezet. Zo hoefden we geen monteur te bellen.",
       [("Qual era o sintoma?", ["*Ficava água dentro","Fazia barulho","Não ligava"]),("Qual era a causa?", ["*Um filtro entupido","Falta de eletricidade","Um cano roto"]),("Precisaram de técnico?", ["*Não","Sim","Ainda não sabem"])],
       "Problema → causa → consequência → solução.", ["v-oorzaak","v-gevolg","v-stap-voor-stap"]),
    FE(["Het","gevolg","waren","een","vieze","geur."], 2, "was", "Sujeito singular: was.", ["v-gevolg"]),
    FB("Het ___ van de storm: drie dagen geen stroom.", ["gevolg"], "Consequência.", ["v-gevolg"], choices=["gevolg","oorzaak","stap"], tr="A consequência da tempestade: três dias sem eletricidade."),
    LI("Eerst hebben we de oorzaak gezocht en toen een oplossing bedacht.", ["Eerst hebben we de oorzaak gezocht en toen een oplossing bedacht"], "Primeiro procurámos a causa e depois pensámos numa solução.", "Sequência.", ["v-oorzaak","v-oplossing"]),
    SW("Descreva um problema que teve em casa ou no trabalho (5–6 frases): o problema, a causa, a consequência e como o resolveu passo a passo.", ["Vorige maand had ik geen internet thuis. De oorzaak was een kapotte router. Het gevolg was dat ik niet kon thuiswerken. Eerst heb ik de provider gebeld. Daarna kreeg ik binnen twee dagen een nieuwe router. Ik heb hem stap voor stap geïnstalleerd en nu werkt alles weer."], ["Problema", "Causa", "Consequência", "Solução passo a passo (eerst, daarna…)"], 50, "Relato estruturado.", ["v-oorzaak","v-gevolg"]),
  ], diff=4, mins=8)

W()
